import type { FastifyError, FastifyInstance, FastifyReply } from 'fastify';

import { ApiError, type ErrorBody } from './errors.js';

const JSON_CONTENT_TYPE = 'application/json; charset=utf-8';

function send(reply: FastifyReply, status: number, body: ErrorBody): FastifyReply {
  return reply.code(status).header('content-type', JSON_CONTENT_TYPE).send(body);
}

/**
 * Fastify 내장 스키마 검증 실패를 계약 포맷의 422로 옮긴다.
 * 라우트는 원칙적으로 바디 스키마를 붙이지 않지만(fastify-project-conventions),
 * 파라미터 검증 등이 걸렸을 때 400/500이 새어나가지 않게 하는 안전망이다.
 */
function validationToBody(error: FastifyError): ErrorBody {
  const errors: Record<string, string[]> = {};
  for (const issue of error.validation ?? []) {
    const raw = (issue.instancePath || '').replace(/^\//, '').replace(/\//g, '.');
    const field = raw || String(issue.params?.missingProperty ?? 'body');
    (errors[field] ??= []).push(issue.message ?? 'is invalid');
  }
  return { errors: Object.keys(errors).length > 0 ? errors : { body: ['is invalid'] } };
}

export function registerErrorHandling(app: FastifyInstance): void {
  app.setErrorHandler((error, request, reply) => {
    if (error instanceof ApiError) {
      return send(reply, error.status, error.body);
    }

    if (error.validation) {
      return send(reply, 422, validationToBody(error));
    }

    request.log.error({ err: error }, 'unhandled error');
    return send(reply, 500, { errors: { server: ['internal error'] } });
  });

  app.setNotFoundHandler((_request, reply) => {
    return send(reply, 404, { errors: { route: ['not found'] } });
  });
}

